def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    HIGH_BID = 91.0

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return max(0.0, min(budget, 1.0))

    units = int(supply // WATER_REQ)
    if units < 0:
        units = 0

    active_threats = []
    max_prev_bid = 0.0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid')
        if prev_bid is None:
            prev_bid = 0.0
        if prev_bid > max_prev_bid:
            max_prev_bid = prev_bid
        if opp.get('budget', 0) > 0:
            active_threats.append((oid, opp, prev_bid))

    if not active_threats:
        return max(0.0, min(budget, 1.0))

    cindy_like = False
    for oid, opp, prev_bid in active_threats:
        req = opp.get('water_requirement', 0)
        sal = opp.get('daily_salary', 0)
        if prev_bid >= 89 and req == 13 and sal == 70:
            cindy_like = True

    urgent = hp <= 2 or no_water >= 2
    very_urgent = hp <= 1 or no_water >= 3

    if very_urgent:
        return max(0.0, min(budget, HIGH_BID if budget >= HIGH_BID else budget))

    if units >= len(active_threats) + 1:
        return max(0.0, min(budget, 0.0))

    if units >= 2 and cindy_like and len(active_threats) == 1:
        if urgent:
            return max(0.0, min(budget, 5.0))
        return max(0.0, min(budget, 0.0))

    if units <= 0:
        return 0.0

    if units == 1:
        if cindy_like:
            if urgent or day >= 8:
                return max(0.0, min(budget, HIGH_BID if budget >= HIGH_BID else budget))
            return max(0.0, min(budget, 0.0))
        target = max(35.0, min(80.0, max_prev_bid + 2.0))
        if urgent:
            target = max(target, 75.0)
        return max(0.0, min(budget, target))

    if urgent:
        return max(0.0, min(budget, 8.0))
    return max(0.0, min(budget, 0.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace only
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Baseline target bid: Cindy appears to anchor around 90.
    # We undercut slightly unless supply is tight.
    tight_supply = supply <= 19.0
    very_tight_supply = supply <= 17.0

    # If someone previously overpaid heavily, raise bid to avoid losing the scarce slot.
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Compute a conservative cap based on remaining budget and urgency.
    urgency = 0
    if my_hp <= 2:
        urgency = 3
    elif my_hp <= 4:
        urgency = 2
    elif no_water_days >= 2:
        urgency = 1

    # Decision
    if very_tight_supply:
        # Need water; bid near Cindy's anchor but not equal.
        base = DAILY_SALARY * 0.92
    elif tight_supply:
        base = DAILY_SALARY * 0.78
    else:
        # Plenty of supply: bid lower to preserve budget.
        base = DAILY_SALARY * 0.55

    # If opponent previously bid extremely high, match pressure.
    if highest_prev_bid >= DAILY_SALARY * 1.15:
        base = max(base, DAILY_SALARY * 0.95)
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        base = max(base, DAILY_SALARY * 0.80)

    # Urgency adjustment
    if urgency >= 3:
        base = max(base, DAILY_SALARY * 0.98)
    elif urgency == 2:
        base = max(base, DAILY_SALARY * 0.90)
    elif urgency == 1:
        base = max(base, DAILY_SALARY * 0.75)

    # Ensure we don't exceed budget.
    bid = min(my_budget, base)

    # Additional safeguard: if budget is very low, bid what we can.
    if my_budget <= DAILY_SALARY * 0.2:
        bid = my_budget

    # Keep bid non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)
